'use client';

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  useSyncExternalStore,
  type CSSProperties,
  type JSX,
  type ReactNode,
} from 'react';
import {
  Button as AriaButton,
  I18nProvider,
  Text,
  UNSTABLE_Toast as AriaToast,
  UNSTABLE_ToastContent as AriaToastContent,
  UNSTABLE_ToastQueue as AriaToastQueue,
  UNSTABLE_ToastRegion as AriaToastRegion,
  isRTL,
  useLocale,
  type QueuedToast,
  type ToastRegionProps as AriaToastRegionProps,
} from 'react-aria-components';
import {
  IconAlertCircleFilled,
  IconAlertTriangleFilled,
  IconCircleCheckFilled,
  IconInfoCircleFilled,
  IconX,
} from '@tabler/icons-react';
import styles from './toast.module.css';

const cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(' ');

/* ------------------------------------------------------------------ *
 * Queue + imperative API
 * ------------------------------------------------------------------ */

export type ToastTone = 'neutral' | 'info' | 'success' | 'warning' | 'danger';

export interface ToastContent {
  title: ReactNode;
  description?: ReactNode;
  tone?: ToastTone;
  /** One short action, e.g. Undo. Pressing it runs `onAction` and closes the toast. */
  action?: { label: string; onAction: () => void };
}

export interface ToastOptions {
  /**
   * Auto-dismiss after this many ms. Default 5000, or no timeout when the toast has an action
   * (keyboard users need time to reach it). `null` keeps the toast until dismissed.
   */
  timeout?: number | null;
  /** Called after the toast is removed, by the user, a timeout or toast.dismiss(). */
  onClose?: () => void;
}

const DEFAULT_TIMEOUT = 5000;

const motionAllowed = (): boolean =>
  typeof window !== 'undefined' &&
  typeof window.matchMedia === 'function' &&
  window.matchMedia('(prefers-reduced-motion: no-preference)').matches;

/**
 * React Aria's ToastQueue, plus an exit phase: close() marks a rendered toast as exiting, the toast
 * plays its exit animation, then finishClose() removes it. Unrendered toasts, or reduced motion,
 * close immediately. Timers, pause-on-hover and focus management stay React Aria's.
 */
class StrataToastQueue extends AriaToastQueue<ToastContent> {
  #exiting: ReadonlySet<string> = new Set();
  #rendered = new Set<string>();
  #listeners = new Set<() => void>();

  override close(key: string): void {
    if (this.#exiting.has(key)) return;
    if (!this.#rendered.has(key) || !motionAllowed()) {
      super.close(key);
      return;
    }
    this.#exiting = new Set(this.#exiting).add(key);
    this.#emit();
    // Safety net in case animationend never arrives (hidden tab, animation overridden).
    setTimeout(() => this.finishClose(key), 2000);
  }

  finishClose(key: string): void {
    if (!this.#exiting.has(key)) return;
    const next = new Set(this.#exiting);
    next.delete(key);
    this.#exiting = next;
    super.close(key);
    this.#emit();
  }

  override clear(): void {
    this.#exiting = new Set();
    super.clear();
    this.#emit();
  }

  markRendered(key: string, rendered: boolean): void {
    if (rendered) this.#rendered.add(key);
    else this.#rendered.delete(key);
  }

  subscribeExiting = (fn: () => void): (() => void) => {
    this.#listeners.add(fn);
    return () => this.#listeners.delete(fn);
  };

  getExiting = (): ReadonlySet<string> => this.#exiting;

  #emit(): void {
    for (const fn of this.#listeners) fn();
  }
}

const queue = new StrataToastQueue({ maxVisibleToasts: 3 });

function showToast(content: ToastContent | string, options: ToastOptions = {}): string {
  const data = typeof content === 'string' ? { title: content } : content;
  const timeout = options.timeout === undefined ? (data.action ? undefined : DEFAULT_TIMEOUT) : (options.timeout ?? undefined);
  return queue.add(data, { timeout, onClose: options.onClose });
}

/**
 * Shows a toast and returns its key. Needs one <ToastRegion /> mounted inside your ThemeScope.
 *   toast({ title: 'Saved', tone: 'success' })
 *   const key = toast({ title: 'Uploading…' }, { timeout: null }); toast.dismiss(key);
 */
export const toast = Object.assign(showToast, {
  /** Closes one toast, or every toast when called without a key. */
  dismiss(key?: string): void {
    if (key === undefined) queue.clear();
    else queue.close(key);
  },
});

/* ------------------------------------------------------------------ *
 * Region
 * ------------------------------------------------------------------ */

export type ToastPlacement = 'top-start' | 'top' | 'top-end' | 'bottom-start' | 'bottom' | 'bottom-end';

export interface ToastRegionProps
  extends Omit<AriaToastRegionProps<ToastContent>, 'queue' | 'children' | 'className' | 'style'> {
  /** Corner or edge of the viewport the stack grows from. */
  placement?: ToastPlacement;
  className?: string;
}

/** The theme and direction of wherever <ToastRegion /> is mounted, forwarded to its portalled element. */
interface Scope {
  theme?: string;
  scheme?: string;
  density?: string;
  lang?: string;
  dir?: string;
}

const SCOPE_ATTRS = ['data-strata-theme', 'data-strata-scheme', 'data-strata-density', 'dir', 'lang'];

function readScope(anchor: Element): Scope {
  // Each attribute on its own: a single-tenant app themes :root and scopes only the scheme.
  const read = (name: string) => anchor.closest(`[${name}]`)?.getAttribute(name) ?? undefined;
  return {
    theme: read('data-strata-theme'),
    scheme: read('data-strata-scheme'),
    density: read('data-strata-density'),
    lang: anchor.closest('[lang]')?.getAttribute('lang') || undefined,
    dir: anchor.closest('[dir]')?.getAttribute('dir') ?? undefined,
  };
}

const sameScope = (a: Scope, b: Scope) =>
  a.theme === b.theme && a.scheme === b.scheme && a.density === b.density && a.lang === b.lang && a.dir === b.dir;

/* Only one mounted region renders the queue; extra <ToastRegion />s (e.g. one per docs example) wait their turn. */
let owner: symbol | null = null;
const ownerListeners = new Set<() => void>();

interface Layout {
  /** Position among live toasts, newest = 0. */
  index: number;
  /** Sum of the heights of newer live toasts, px. */
  offset: number;
}

interface RegionContextValue {
  layout: Map<string, Layout>;
  count: number;
  frontHeight?: number;
  heights: Record<string, number>;
  exiting: ReadonlySet<string>;
  reportHeight: (key: string, height: number) => void;
}

const RegionContext = createContext<RegionContextValue | null>(null);

/**
 * Where toasts appear. Mount one inside your app's ThemeScope (e.g. next to your layout's
 * children). Toasts portal to <body>, so the region copies the theme, scheme, density, lang and dir
 * of the spot where it is mounted onto the portalled element — they look and read like the page.
 */
export function ToastRegion({ placement = 'bottom-end', className, ...rest }: ToastRegionProps): JSX.Element {
  const anchorRef = useRef<HTMLSpanElement>(null);
  const [id] = useState(() => Symbol('ToastRegion'));
  const [isOwner, setIsOwner] = useState(false);
  const [scope, setScope] = useState<Scope>({});
  const [heights, setHeights] = useState<Record<string, number>>({});
  const outer = useLocale();

  const visible = useSyncExternalStore(
    (fn) => queue.subscribe(fn),
    () => queue.visibleToasts,
    () => queue.visibleToasts,
  );
  const exiting = useSyncExternalStore(queue.subscribeExiting, queue.getExiting, queue.getExiting);

  useEffect(() => {
    const claim = () => {
      if (owner === null) owner = id;
      setIsOwner(owner === id);
    };
    claim();
    ownerListeners.add(claim);
    return () => {
      ownerListeners.delete(claim);
      if (owner === id) {
        owner = null;
        for (const fn of ownerListeners) fn();
      }
    };
  }, [id]);

  useLayoutEffect(() => {
    const anchor = anchorRef.current;
    if (!anchor) return;
    const update = () => {
      const next = readScope(anchor);
      setScope((prev) => (sameScope(prev, next) ? prev : next));
    };
    update();
    if (typeof MutationObserver === 'undefined') return;
    const observer = new MutationObserver(update);
    observer.observe(document.documentElement, { attributes: true, subtree: true, attributeFilter: SCOPE_ATTRS });
    return () => observer.disconnect();
  }, []);

  // Forget heights of toasts that are gone.
  useEffect(() => {
    setHeights((prev) => {
      const keys = Object.keys(prev).filter((k) => visible.some((t) => t.key === k));
      return keys.length === Object.keys(prev).length ? prev : Object.fromEntries(keys.map((k) => [k, prev[k] ?? 0]));
    });
  }, [visible]);

  // Stack geometry: exiting toasts keep the slot they had, so the rest can close the gap while they fade.
  const lastLayout = useRef(new Map<string, Layout>());
  const layout = new Map<string, Layout>();
  let offset = 0;
  let index = 0;
  for (const t of visible) {
    if (exiting.has(t.key)) continue;
    layout.set(t.key, { index, offset });
    offset += heights[t.key] ?? 0;
    index += 1;
  }
  for (const t of visible) {
    const previous = lastLayout.current.get(t.key);
    if (exiting.has(t.key)) layout.set(t.key, previous ?? { index: 0, offset: 0 });
  }
  lastLayout.current = layout;
  const front = visible.find((t) => !exiting.has(t.key));

  const reportHeight = useCallback(
    (key: string, height: number) => setHeights((prev) => (prev[key] === height ? prev : { ...prev, [key]: height })),
    [],
  );
  const context: RegionContextValue = {
    layout,
    count: visible.length,
    frontHeight: front ? heights[front.key] : undefined,
    heights,
    exiting,
    reportHeight,
  };

  // A page can be RTL (dir + lang on the ThemeScope) while React Aria's locale is still LTR, e.g. no
  // I18nProvider. React Aria sets `dir` on the region from its locale, so when the page's own lang
  // explains its direction, use that lang for the region (this also localises "Close").
  const pageRTL = scope.dir === 'rtl' ? true : scope.dir === 'ltr' ? false : undefined;
  const fixLocale =
    pageRTL !== undefined && pageRTL !== isRTL(outer.locale) && scope.lang && isRTL(scope.lang) === pageRTL
      ? scope.lang
      : undefined;

  const region = (
    <AriaToastRegion
      {...rest}
      queue={queue}
      lang={scope.lang}
      data-strata-theme={scope.theme}
      data-strata-scheme={scope.scheme}
      data-strata-density={scope.density}
      data-placement={placement}
      className={cx(styles.region, className)}
    >
      {({ toast: item }) => <ToastItem toast={item} />}
    </AriaToastRegion>
  );

  return (
    <>
      <span ref={anchorRef} hidden data-strata-toast-anchor="" />
      {isOwner && (
        <RegionContext.Provider value={context}>
          {fixLocale ? <I18nProvider locale={fixLocale}>{region}</I18nProvider> : region}
        </RegionContext.Provider>
      )}
    </>
  );
}

/* ------------------------------------------------------------------ *
 * Toast
 * ------------------------------------------------------------------ */

const TONE_ICON: Record<Exclude<ToastTone, 'neutral'>, typeof IconInfoCircleFilled> = {
  info: IconInfoCircleFilled,
  success: IconCircleCheckFilled,
  warning: IconAlertTriangleFilled,
  danger: IconAlertCircleFilled,
};

function ToastItem({ toast: item }: { toast: QueuedToast<ToastContent> }): JSX.Element {
  const region = useContext(RegionContext);
  const innerRef = useRef<HTMLDivElement>(null);
  const toastRef = useRef<HTMLDivElement>(null);
  const { key, content } = item;
  const tone = content.tone ?? 'neutral';
  const ToneIcon = tone === 'neutral' ? null : TONE_ICON[tone];
  const isExiting = region?.exiting.has(key) ?? false;
  const slot = region?.layout.get(key) ?? { index: 0, offset: 0 };
  const height = region?.heights[key];
  const reportHeight = region?.reportHeight;

  useEffect(() => {
    queue.markRendered(key, true);
    return () => queue.markRendered(key, false);
  }, [key]);

  // Measure the natural (untransformed, unclipped) height so the stack can lay out real offsets.
  useLayoutEffect(() => {
    const inner = innerRef.current;
    const outer = toastRef.current;
    if (!inner || !outer || !reportHeight) return;
    const measure = () => reportHeight(key, inner.offsetHeight + (outer.offsetHeight - outer.clientHeight));
    measure();
    if (typeof ResizeObserver === 'undefined') return;
    const observer = new ResizeObserver(measure);
    observer.observe(inner);
    return () => observer.disconnect();
  }, [key, reportHeight]);

  const style = {
    '--_index': slot.index,
    '--_offset': `${slot.offset}px`,
    '--_front-h': region?.frontHeight !== undefined ? `${region.frontHeight}px` : undefined,
    '--_self-h': height !== undefined ? `${height}px` : undefined,
    zIndex: (region?.count ?? 1) - slot.index,
  } as CSSProperties;

  return (
    <AriaToast
      toast={item}
      ref={toastRef}
      style={style}
      data-tone={tone}
      data-front={slot.index === 0 && !isExiting ? '' : undefined}
      data-exiting={isExiting || undefined}
      onAnimationEnd={(e) => {
        if (isExiting && e.target === e.currentTarget) queue.finishClose(key);
      }}
      className={styles.toast}
    >
      <div ref={innerRef} className={styles.inner}>
        {ToneIcon && (
          <span className={styles.icon} aria-hidden="true">
            <ToneIcon />
          </span>
        )}
        <AriaToastContent className={styles.content}>
          <Text slot="title" className={styles.title}>
            {content.title}
          </Text>
          {content.description != null && content.description !== false && (
            <Text slot="description" className={styles.description}>
              {content.description}
            </Text>
          )}
        </AriaToastContent>
        {content.action && (
          <AriaButton
            className={styles.action}
            onPress={() => {
              content.action?.onAction();
              queue.close(key);
            }}
          >
            {content.action.label}
          </AriaButton>
        )}
        <AriaButton slot="close" className={styles.close}>
          <IconX aria-hidden="true" stroke={2} />
        </AriaButton>
      </div>
    </AriaToast>
  );
}

/*
 * Toast region + stacked toasts.
 *
 * All toasts share one grid cell. Collapsed, older toasts sit behind the newest, shifted by a small
 * peek and scaled down, clipped to the front toast's height. Hovered or keyboard-focused, the stack
 * fans out to real positions using heights measured in JS (--_offset, --_self-h).
 *   --_sign  −1 when older toasts stack upward (bottom placements), +1 downward (top placements)
 */

.region {
  --_gap: var(--strata-space-3);
  --_peek: var(--strata-space-3);
  --_sign: -1;
  --_enter: 1;
  /* 16px on phones, 24px from ~600px up (percentages resolve against the viewport for a fixed box). */
  --_edge: clamp(var(--strata-space-4), 4%, var(--strata-space-6));
  --_width: calc(var(--strata-space-16) * 5.5);

  position: fixed;
  z-index: 9999;
  inset-block-end: var(--_edge);
  inset-inline-end: var(--_edge);
  box-sizing: border-box;
  display: grid;
  inline-size: min(var(--_width), calc(100% - var(--_edge) * 2));
  color: var(--strata-color-text-default);
  font-family: var(--strata-font-body);
  font-size: var(--strata-font-size-sm);
  line-height: var(--strata-line-height-normal);
  text-align: start;
  outline: none;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.region :where(*, *::before, *::after) {
  box-sizing: border-box;
}

.region[data-placement='bottom-start'] {
  inset-inline: var(--_edge) auto;
}

.region[data-placement='bottom'],
.region[data-placement='top'] {
  inset-inline: 0;
  margin-inline: auto;
}

.region[data-placement^='top'] {
  --_sign: 1;
  --_enter: -1;

  inset-block: var(--_edge) auto;
}

.region[data-placement='top-start'] {
  inset-inline: var(--_edge) auto;
}

.region[data-focus-visible] {
  outline: 2px solid var(--strata-color-focus-ring);
  outline-offset: 2px;
  border-radius: var(--strata-radius-container);
}

/* ---- toast ------------------------------------------------------------- */

.toast {
  position: relative;
  grid-area: 1 / 1;
  align-self: end;
  inline-size: 100%;
  border: 1px solid var(--strata-color-border-default);
  border-radius: var(--strata-radius-container);
  background-color: var(--strata-color-surface-raised);
  box-shadow: var(--strata-shadow-overlay);
  color: var(--strata-color-text-default);
  outline: none;
  /* Collapsed: peek out behind the newer toasts, a little smaller each step back. */
  translate: 0 calc(var(--_index) * var(--_peek) * var(--_sign));
  scale: calc(1 - var(--_index) * 0.05);
  transform-origin: 50% 0;
}

.region[data-placement^='top'] .toast {
  align-self: start;
  transform-origin: 50% 100%;
}

.toast[data-focus-visible] {
  outline: 2px solid var(--strata-color-focus-ring);
  outline-offset: 2px;
}

/* Bridges the gap between fanned-out toasts so the pointer never "leaves" the stack between them. */
.toast::after {
  position: absolute;
  inset-inline: 0;
  inset-block-start: 100%;
  block-size: var(--_gap);
  content: '';
}

.region[data-placement^='top'] .toast::after {
  inset-block: auto 100%;
}

.toast:not([data-front]):not([data-exiting]) {
  block-size: var(--_front-h, auto);
  overflow: hidden;
}

.toast:not([data-front]):not([data-exiting]) > .inner {
  opacity: 0;
}

/* Expanded: hover or keyboard focus fans the stack out. (After the collapsed rules: same specificity.) */
.region:is([data-hovered], :has(:focus-visible)) .toast {
  translate: 0 calc((var(--_offset) + var(--_index) * var(--_gap)) * var(--_sign));
  scale: 1;
  block-size: var(--_self-h, auto);
}

.region:is([data-hovered], :has(:focus-visible)) .toast > .inner {
  opacity: 1;
}

/* ---- content ----------------------------------------------------------- */

.inner {
  --_line: calc(var(--strata-font-size-md) * var(--strata-line-height-snug));

  display: flex;
  align-items: flex-start;
  gap: var(--strata-space-3);
  padding-block: var(--strata-space-4);
  padding-inline: var(--strata-space-4) var(--strata-space-3);
}

.icon {
  display: inline-flex;
  flex: none;
  align-items: center;
  block-size: var(--_line);
}

.icon > svg {
  inline-size: calc(var(--strata-font-size-md) * 1.2);
  block-size: calc(var(--strata-font-size-md) * 1.2);
}

.toast[data-tone='info'] .icon {
  color: var(--strata-color-feedback-info-fg);
}
.toast[data-tone='success'] .icon {
  color: var(--strata-color-feedback-success-fg);
}
.toast[data-tone='warning'] .icon {
  color: var(--strata-color-feedback-warning-fg);
}
.toast[data-tone='danger'] .icon {
  color: var(--strata-color-feedback-danger-fg);
}

.content {
  display: grid;
  flex: 1 1 0;
  gap: calc(var(--strata-space-1) * 0.5);
  min-inline-size: 0;
}

.title {
  display: block;
  color: var(--strata-color-text-default);
  font-size: var(--strata-font-size-md);
  font-weight: var(--strata-font-weight-semibold);
  letter-spacing: 0;
  line-height: var(--strata-line-height-snug);
  overflow-wrap: anywhere;
}

.description {
  display: block;
  color: var(--strata-color-text-subtle);
  font-size: var(--strata-font-size-sm);
  line-height: var(--strata-line-height-normal);
  overflow-wrap: anywhere;
  text-wrap: pretty;
}

.action {
  display: inline-flex;
  flex: none;
  align-items: center;
  align-self: center;
  justify-content: center;
  min-block-size: calc(var(--strata-space-6) + var(--strata-space-1));
  margin: 0;
  padding-block: 0;
  padding-inline: var(--strata-space-3);
  border: 1px solid color-mix(in oklab, var(--strata-color-action-secondary-fg) 18%, transparent);
  border-radius: var(--strata-radius-button);
  background-color: var(--strata-color-action-secondary-bg);
  color: var(--strata-color-action-secondary-fg);
  font-family: inherit;
  font-size: var(--strata-font-size-sm);
  font-weight: var(--strata-font-weight-semibold);
  line-height: 1;
  white-space: nowrap;
  cursor: default;
  outline: none;
}

.action[data-hovered] {
  background-color: var(--strata-color-action-secondary-hover);
}

.action[data-pressed] {
  background-color: var(--strata-color-action-secondary-pressed);
}

/* 24px hit target (WCAG 2.5.8), centred on the title's first line. */
.close {
  display: inline-grid;
  flex: none;
  place-items: center;
  inline-size: var(--strata-space-6);
  block-size: var(--strata-space-6);
  margin-block: calc((var(--_line) - var(--strata-space-6)) / 2);
  margin-inline: 0;
  padding: 0;
  border: 0;
  border-radius: min(var(--strata-radius-button), var(--strata-space-2));
  background-color: transparent;
  color: var(--strata-color-text-subtle);
  cursor: default;
  outline: none;
}

.close > svg {
  inline-size: var(--strata-space-4);
  block-size: var(--strata-space-4);
}

.close[data-hovered] {
  background-color: color-mix(in oklab, var(--strata-color-text-default) 6%, transparent);
  color: var(--strata-color-text-default);
}

.close[data-pressed] {
  background-color: color-mix(in oklab, var(--strata-color-text-default) 10%, transparent);
}

.action[data-focus-visible],
.close[data-focus-visible] {
  outline: 2px solid var(--strata-color-focus-ring);
  outline-offset: 2px;
}

/* ---- motion ------------------------------------------------------------ */

@media (prefers-reduced-motion: no-preference) {
  .toast {
    animation: strata-toast-in calc(var(--strata-motion-duration-normal) * 2) var(--strata-motion-easing);
    transition:
      translate calc(var(--strata-motion-duration-normal) * 2) var(--strata-motion-easing),
      scale calc(var(--strata-motion-duration-normal) * 2) var(--strata-motion-easing),
      block-size calc(var(--strata-motion-duration-normal) * 2) var(--strata-motion-easing);
  }

  .toast > .inner {
    transition: opacity var(--strata-motion-duration-normal) var(--strata-motion-easing);
  }

  .toast[data-exiting] {
    animation: strata-toast-out var(--strata-motion-duration-normal) var(--strata-motion-easing) forwards;
    pointer-events: none;
  }

  .close,
  .action {
    transition: background-color var(--strata-motion-duration-fast) var(--strata-motion-easing);
  }
}

@keyframes strata-toast-in {
  from {
    opacity: 0;
    transform: translateY(calc(var(--_enter) * (100% + var(--_edge))));
  }
}

@keyframes strata-toast-out {
  to {
    opacity: 0;
    transform: translateY(calc(var(--_enter) * 30%)) scale(0.97);
  }
}
